    $v=api_input();$allowed=array_intersect_key($v,array_flip(['name','minAge','maxAge','ageLabel','displayOrder','active']));if(!$allowed)api_error('VALIDATION_ERROR','No editable class fields were supplied.',422);$map=['minAge'=>'min_age','maxAge'=>'max_age','ageLabel'=>'age_label','displayOrder'=>'display_order','active'=>'is_active'];$sets=[];$params=[];foreach($allowed as $k=>$value){$sets[]=($map[$k]??$k).'=?';$params[]=$value;}$params[]=$id;$db->prepare('UPDATE classes SET '.implode(',',$sets).' WHERE id=?')->execute($params);api_audit($db,$actor,'CLASS_UPDATED','Class',$id,$allowed);api_ok(['id'=>$id,'updated'=>true]);
