    $actor=api_actor($db);[$page,$limit,$offset]=api_page();$where=[];$params=[];$allowed=api_permitted_class_ids($db,$actor);
    if($allowed!==null){if(!$allowed)api_ok([],200,['page'=>$page,'limit'=>$limit,'total'=>0,'totalPages'=>1]);$where[]='c.class_id IN ('.implode(',',array_fill(0,count($allowed),'?')).')';$params=array_merge($params,$allowed);}
    if(($q=trim((string)($_GET['search']??'')))!==''){$where[]='(c.first_name LIKE ? OR c.last_name LIKE ?)';$params[]="%$q%";$params[]="%$q%";}
    foreach(['classId'=>'c.class_id','gender'=>'c.gender'] as $query=>$column)if(isset($_GET[$query])&&$_GET[$query]!==''){$where[]="$column=?";$params[]=$_GET[$query];}
    if(isset($_GET['active'])){$where[]='c.is_active=?';$params[]=filter_var($_GET['active'],FILTER_VALIDATE_BOOLEAN)?1:0;}
    if(isset($_GET['classAssignmentRequired'])){$where[]='c.class_assignment_required=?';$params[]=filter_var($_GET['classAssignmentRequired'],FILTER_VALIDATE_BOOLEAN)?1:0;}
    $filter=$where?' WHERE '.implode(' AND ',$where):'';$sort=['name'=>'c.first_name','firstName'=>'c.first_name','lastName'=>'c.last_name','dateOfBirth'=>'c.date_of_birth','classId'=>'c.class_id'][$_GET['sort']??'name']??'c.first_name';$order=strtolower((string)($_GET['order']??'asc'))==='desc'?'DESC':'ASC';
    $count=$db->prepare("SELECT COUNT(*) FROM children c$filter");$count->execute($params);$total=(int)$count->fetchColumn();$s=$db->prepare('SELECT '.api_child_select()." FROM children c LEFT JOIN classes cl ON cl.id=c.class_id$filter ORDER BY $sort $order,c.last_name LIMIT $limit OFFSET $offset");$s->execute($params);api_ok($s->fetchAll(),200,['page'=>$page,'limit'=>$limit,'total'=>$total,'totalPages'=>max(1,(int)ceil($total/$limit))]);
}
