function api_child_guardians(PDO $db,int $childId): never { $actor=api_actor($db);api_child_allowed($db,$actor,$childId);$s=$db->prepare('SELECT g.id,g.first_name AS firstName,g.last_name AS lastName,g.phone AS primaryPhone,g.email,cg.relationship,cg.is_primary AS primary,cg.authorised_pickup AS authorisedPickup FROM child_guardians cg JOIN guardians g ON g.id=cg.guardian_id WHERE cg.child_id=?');$s->execute([$childId]);api_ok($s->fetchAll()); }
function api_profile(PDO $db,int $childId,string $table): never { $actor=api_actor($db,true);api_child_allowed($db,$actor,$childId);if(api_method()==='GET'){$s=$db->prepare("SELECT * FROM $table WHERE child_id=?");$s->execute([$childId]);api_ok($s->fetch()?:null);}$v=api_input();$valid=array_column($db->query("SHOW COLUMNS FROM $table")->fetchAll(),'Field');$fields=array_values(array_filter(array_keys($v),fn($key)=>in_array($key,$valid,true)&&!in_array($key,['child_id','created_at','updated_at'],true)));if(!$fields)api_error('VALIDATION_ERROR','No recognised profile fields were supplied.',422);$cols=implode(',', $fields);$marks=implode(',',array_fill(0,count($fields),'?'));$sets=implode(',',array_map(fn($f)=>"$f=VALUES($f)",$fields));$s=$db->prepare("INSERT INTO $table(child_id,$cols) VALUES(?,$marks) ON DUPLICATE KEY UPDATE $sets");$s->execute(array_merge([$childId],array_map(fn($f)=>$v[$f],$fields)));api_audit($db,$actor,'CHILD_PROFILE_UPDATED','Child',$childId,['profile'=>$table]);api_ok(['childId'=>$childId,'updated'=>true]); }
function api_public_lookup(PDO $db): never { $v=api_input();$phone=api_phone($v['phone']??null);$sessionId=(int)($v['serviceSessionId']??0);if(!$phone||!$sessionId)api_error('VALIDATION_ERROR','A valid phone number and service session are required.',422);$s=$db->query('SELECT id,first_name,last_name,phone FROM guardians');$guardian=null;foreach($s->fetchAll() as $row)if(api_phone($row['phone'])===$phone){$guardian=$row;break;}if(!$guardian)api_ok(['guardianFirstName'=>null,'children'=>[]]);$children=$db->prepare("SELECT c.id,c.first_name AS firstName,CONCAT(LEFT(c.last_name,1),'.') AS lastInitial,cl.name AS className,a.checked_in_at AS checkedInAt,CASE WHEN a.status IN ('CHECKED_IN','PICKED_UP') THEN TRUE ELSE FALSE END AS alreadyCheckedIn FROM child_guardians cg JOIN children c ON c.id=cg.child_id LEFT JOIN classes cl ON cl.id=c.class_id LEFT JOIN attendance a ON a.child_id=c.id AND a.service_session_id=? WHERE cg.guardian_id=? ORDER BY c.first_name");$children->execute([$sessionId,$guardian['id']]);api_ok(['guardianFirstName'=>$guardian['first_name'],'children'=>$children->fetchAll()]); }
function api_sessions(PDO $db): never { $actor=api_actor($db);$where=['campus_id=?'];$params=[$actor['campus_id']];if(isset($_GET['date'])){$where[]='service_date=?';$params[]=$_GET['date'];}if(isset($_GET['service'])){$where[]='service_type=?';$params[]=$_GET['service'];}$s=$db->prepare('SELECT id,campus_id AS campusId,name,service_date AS serviceDate,service_type AS serviceType,starts_at AS startsAt,ends_at AS endsAt,is_open AS isOpen FROM service_sessions WHERE '.implode(' AND ',$where).' ORDER BY starts_at DESC');$s->execute($params);api_ok($s->fetchAll()); }
