function api_roster(PDO $db): never { $actor=api_actor($db,true);$where=['1=1'];$params=[];foreach(['userId'=>'ra.user_id','dutyTypeId'=>'ra.duty_type_id','classId'=>'ra.class_id','serviceSessionId'=>'ra.service_session_id'] as $key=>$col)if(isset($_GET[$key])){$where[]="$col=?";$params[]=(int)$_GET[$key];}if(isset($_GET['month'])){$where[]='MONTH(ra.assignment_date)=?';$params[]=(int)$_GET['month'];}if(isset($_GET['year'])){$where[]='YEAR(ra.assignment_date)=?';$params[]=(int)$_GET['year'];}$s=$db->prepare('SELECT ra.id,ra.user_id AS userId,ra.assignment_date AS assignmentDate,ra.service_session_id AS serviceSessionId,ra.class_id AS classId,ra.status,ra.confirmed_at AS confirmedAt,dt.name AS dutyName,dt.code AS dutyCode,c.name AS className,u.name AS teacherName FROM roster_assignments ra JOIN staff_users u ON u.id=ra.user_id JOIN duty_types dt ON dt.id=ra.duty_type_id LEFT JOIN classes c ON c.id=ra.class_id WHERE '.implode(' AND ',$where).' ORDER BY ra.assignment_date,ra.id');$s->execute($params);api_ok($s->fetchAll()); }
function api_my_roster(PDO $db,string $scope): never { $actor=api_actor($db);$date=$scope==='today'?' AND ra.assignment_date=CURDATE()':($scope==='upcoming'?' AND ra.assignment_date>=CURDATE()':'');$s=$db->prepare("SELECT ra.id,ra.assignment_date AS assignmentDate,ra.service_session_id AS serviceSessionId,ra.status,ra.confirmed_at AS confirmedAt,dt.name AS dutyName,dt.code AS dutyCode,c.name AS className FROM roster_assignments ra JOIN duty_types dt ON dt.id=ra.duty_type_id LEFT JOIN classes c ON c.id=ra.class_id WHERE ra.user_id=?$date ORDER BY ra.assignment_date,ra.id");$s->execute([$actor['id']]);api_ok($s->fetchAll()); }
