function api_dashboard(PDO $db): never {
    $actor=api_actor($db);$allowed=api_permitted_class_ids($db,$actor);$where=['c.campus_id=?','c.is_active=1'];$params=[$actor['campus_id']];
    if($allowed!==null){if(!$allowed) $where[]='1=0'; else {$where[]='c.id IN ('.implode(',',array_fill(0,count($allowed),'?')).')';$params=array_merge($params,$allowed);}}
    $session=$db->prepare('SELECT id,name,service_type AS serviceType,service_date AS serviceDate FROM service_sessions WHERE campus_id=? AND is_open=1 ORDER BY starts_at DESC LIMIT 1');$session->execute([$actor['campus_id']]);$activeSession=$session->fetch();$sessionId=(int)($activeSession['id']??0);
    $classes=$db->prepare('SELECT c.id,c.name,c.age_label AS ageLabel,COUNT(ch.id) AS total FROM classes c LEFT JOIN children ch ON ch.class_id=c.id AND ch.is_active=1 WHERE '.implode(' AND ',$where).' GROUP BY c.id,c.name,c.age_label ORDER BY c.display_order,c.name');$classes->execute($params);$rows=$classes->fetchAll();$checked=0;$picked=0;
    foreach($rows as &$row){$row['total']=(int)$row['total'];$row['checkedIn']=0;if($sessionId){$a=$db->prepare("SELECT status,COUNT(*) AS amount FROM attendance WHERE service_session_id=? AND class_id=? GROUP BY status");$a->execute([$sessionId,$row['id']]);foreach($a->fetchAll() as $state){$row['checkedIn']+=(int)$state['amount'];$checked+=(int)$state['amount'];if($state['status']==='PICKED_UP')$picked+=(int)$state['amount'];}}}unset($row);
    $personal=$db->prepare("SELECT ra.id,ra.assignment_date AS assignmentDate,dt.name AS dutyName,c.name AS className,ss.name AS serviceName FROM roster_assignments ra JOIN duty_types dt ON dt.id=ra.duty_type_id LEFT JOIN classes c ON c.id=ra.class_id LEFT JOIN service_sessions ss ON ss.id=ra.service_session_id WHERE ra.user_id=? AND ra.status NOT IN ('CANCELLED','REPLACED') AND ra.assignment_date>=CURDATE() ORDER BY ra.assignment_date,ra.id LIMIT 1");$personal->execute([$actor['id']]);$personalAssignment=$personal->fetch()?:null;
    $todayTeam=[];$upcoming=[];$needs=[];$relations=['total'=>0,'contacted'=>0,'pending'=>0];
    if($actor['access_level']==='TPK_SUPER_ADMIN'){
        $team=$db->prepare("SELECT COALESCE(ss.service_type,'UNSCHEDULED') AS serviceType,COUNT(*) AS assigned,SUM(ra.status='PRESENT') AS present,SUM(ra.status='ASSIGNED') AS notConfirmed FROM roster_assignments ra LEFT JOIN service_sessions ss ON ss.id=ra.service_session_id WHERE ra.assignment_date=COALESCE((SELECT service_date FROM service_sessions WHERE id=?),CURDATE()) AND ra.status NOT IN ('CANCELLED','REPLACED') GROUP BY COALESCE(ss.service_type,'UNSCHEDULED')");$team->execute([$sessionId?:null]);$todayTeam=$team->fetchAll();
        $up=$db->prepare("SELECT assignment_date AS assignmentDate,COALESCE(service_session_id,0) AS serviceSessionId,COUNT(*) AS duties,SUM(status NOT IN ('CANCELLED','REPLACED')) AS filled FROM roster_assignments WHERE assignment_date>=CURDATE() AND status NOT IN ('CANCELLED','REPLACED') GROUP BY assignment_date,service_session_id ORDER BY assignment_date LIMIT 2");$up->execute();$upcoming=$up->fetchAll();
        $need=$db->prepare("SELECT 'UNPICKED_UP' AS type,'URGENT' AS severity,CONCAT(COUNT(*),' children are still awaiting pickup') AS message,'Review Pick-Up' AS actionLabel,'/account/pick-up' AS actionDestination FROM attendance WHERE service_session_id=? AND status='CHECKED_IN' HAVING COUNT(*)>0");
        if($sessionId){try{$need->execute([$sessionId]);$needs=$need->fetchAll();}catch(Throwable $e){$needs=[];}}
        $task=$db->prepare("SELECT COUNT(*) AS total,SUM(status='RESOLVED') AS contacted,SUM(status IN ('OPEN','IN_PROGRESS')) AS pending FROM follow_up_tasks WHERE campus_id=?");try{$task->execute([$actor['campus_id']]);$relations=$task->fetch()?:$relations;}catch(Throwable $e){}
        $classNeed=$db->prepare("SELECT COUNT(*) FROM children c JOIN families f ON f.id=c.family_id WHERE f.campus_id=? AND c.class_assignment_required=1 AND c.is_active=1");$classNeed->execute([$actor['campus_id']]);$amount=(int)$classNeed->fetchColumn();if($amount)$needs[]=['type'=>'NEEDS_CLASS_ASSIGNMENT','severity'=>'HIGH','message'=>"{$amount} children need a class assignment",'actionLabel'=>'Assign Class','actionDestination'=>'/account/children'];
    }
    api_ok(['serviceSession'=>$activeSession?:null,'serviceSessionId'=>$sessionId?:null,'metrics'=>['checkedIn'=>$checked,'pickedUp'=>$picked,'stillPresent'=>$checked-$picked,'activeClasses'=>count($rows)],'classes'=>$rows,'personalAssignment'=>$personalAssignment,'todayTeam'=>$todayTeam,'needsAttention'=>$needs,'childrenRelations'=>$relations,'upcomingRoster'=>$upcoming]);
}
function api_checkins(PDO $db): never {
    $actor=api_actor($db);$allowed=api_permitted_class_ids($db,$actor);$sessionId=(int)($_GET['serviceSessionId']??0);
    if(!$sessionId){$current=$db->prepare('SELECT id FROM service_sessions WHERE campus_id=? AND is_open=1 ORDER BY starts_at DESC LIMIT 1');$current->execute([$actor['campus_id']]);$sessionId=(int)$current->fetchColumn();}
    if(!$sessionId)api_ok(['serviceSessionId'=>null,'items'=>[]]);$where=['a.service_session_id=?'];$params=[$sessionId];if($allowed!==null){if(!$allowed)api_ok(['serviceSessionId'=>$sessionId,'items'=>[]]);$where[]='a.class_id IN ('.implode(',',array_fill(0,count($allowed),'?')).')';$params=array_merge($params,$allowed);}
    if(($q=trim((string)($_GET['search']??'')))!==''){$where[]='(c.first_name LIKE ? OR c.last_name LIKE ? OR g.first_name LIKE ? OR g.last_name LIKE ?)';$params=array_merge($params,["%$q%","%$q%","%$q%","%$q%"]);}
    $sql="SELECT a.id,c.id AS childId,c.first_name AS firstName,c.last_name AS lastName,c.gender,cl.name AS className,a.status,a.checked_in_at AS checkedInAt,a.is_first_visit AS firstVisit,g.first_name AS guardianFirstName,g.last_name AS guardianLastName FROM attendance a JOIN children c ON c.id=a.child_id LEFT JOIN classes cl ON cl.id=a.class_id LEFT JOIN child_guardians cg ON cg.child_id=c.id AND cg.is_primary=1 LEFT JOIN guardians g ON g.id=cg.guardian_id WHERE ".implode(' AND ',$where).' ORDER BY a.checked_in_at DESC';$s=$db->prepare($sql);$s->execute($params);api_ok(['serviceSessionId'=>$sessionId,'items'=>$s->fetchAll()]);
}
function api_pickup_code_lookup(PDO $db): never {
    $actor=api_actor($db);$value=trim((string)($_GET['code']??''));if(str_starts_with($value,'TPK-PICKUP:'))$value=substr($value,11);if($value==='')api_error('VALIDATION_ERROR','Scan a pickup QR code or enter a pickup code.',422);
    $where=preg_match('/^[a-f0-9]{64}$/i',$value)?'pc.qr_token=?':'pc.display_code=?';$s=$db->prepare("SELECT pc.id,pc.display_code AS pickupCode,pc.collected_at AS collectedAt,f.surname,ss.name AS serviceName FROM service_pickup_codes pc JOIN families f ON f.id=pc.family_id JOIN service_sessions ss ON ss.id=pc.service_session_id WHERE ss.campus_id=? AND {$where} ORDER BY pc.id DESC LIMIT 1");$s->execute([$actor['campus_id'],$value]);$code=$s->fetch();if(!$code)api_error('PICKUP_CODE_NOT_FOUND','This pickup code is not available at this campus.',404);
    $children=$db->prepare("SELECT a.id AS attendanceId,c.first_name AS firstName,c.last_name AS lastName,cl.name AS className,a.status FROM attendance a JOIN children c ON c.id=a.child_id LEFT JOIN classes cl ON cl.id=a.class_id JOIN service_pickup_codes pc ON pc.service_session_id=a.service_session_id AND pc.family_id=c.family_id WHERE pc.id=? AND a.status='CHECKED_IN' ORDER BY c.first_name");$children->execute([$code['id']]);$code['children']=$children->fetchAll();api_ok($code);
}
function api_assisted_pickup_lookup(PDO $db): never {
    $actor=api_actor($db);$v=api_input();$first=trim((string)($v['firstName']??''));$last=trim((string)($v['lastName']??''));$birthDate=trim((string)($v['dateOfBirth']??''));
    if($first===''||$last===''||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$birthDate)) api_error('VALIDATION_ERROR','Enter the child’s first name, last name, and date of birth.',422);
    $s=$db->prepare("SELECT pc.id,pc.display_code AS pickupCode,pc.collected_at AS collectedAt,f.surname,ss.name AS serviceName FROM service_pickup_codes pc JOIN service_sessions ss ON ss.id=pc.service_session_id JOIN families f ON f.id=pc.family_id JOIN attendance a ON a.service_session_id=pc.service_session_id JOIN children c ON c.id=a.child_id AND c.family_id=pc.family_id WHERE ss.campus_id=? AND c.first_name=? AND c.last_name=? AND c.date_of_birth=? AND a.status='CHECKED_IN' ORDER BY ss.service_date DESC,pc.id DESC LIMIT 1");$s->execute([$actor['campus_id'],$first,$last,$birthDate]);$code=$s->fetch();
    if(!$code) api_error('ASSISTED_PICKUP_NOT_FOUND','We could not verify a checked-in child with those details.',404);
    $children=$db->prepare("SELECT a.id AS attendanceId,c.first_name AS firstName,c.last_name AS lastName,cl.name AS className,a.status FROM attendance a JOIN children c ON c.id=a.child_id LEFT JOIN classes cl ON cl.id=a.class_id JOIN service_pickup_codes pc ON pc.service_session_id=a.service_session_id AND pc.family_id=c.family_id WHERE pc.id=? AND a.status='CHECKED_IN' ORDER BY c.first_name");$children->execute([$code['id']]);$code['children']=$children->fetchAll();
    api_audit($db,$actor,'PICKUP_ASSISTED_BIRTH_DATE_VERIFIED','PickupCode',(int)$code['id'],['pickupCode'=>$code['pickupCode']]);api_ok($code);
}
function api_complete_pickup_code(PDO $db,int $id): never {
    $v=api_input();$verificationMethod=(string)($v['verificationMethod']??'PICKUP_CODE');if(!in_array($verificationMethod,['PICKUP_CODE','QR_CODE','ASSISTED_BIRTH_DATE'],true))api_error('VALIDATION_ERROR','Use an approved pickup verification method.',422);
    $actor=api_actor($db);$s=$db->prepare("SELECT pc.id,pc.service_session_id,pc.family_id,pc.display_code,pc.collected_at FROM service_pickup_codes pc JOIN service_sessions ss ON ss.id=pc.service_session_id WHERE pc.id=? AND ss.campus_id=? FOR UPDATE");$s->execute([$id,$actor['campus_id']]);$code=$s->fetch();if(!$code)api_error('PICKUP_CODE_NOT_FOUND','This pickup code is not available.',404);if($code['collected_at'])api_error('PICKUP_ALREADY_COMPLETED','This pickup code has already been used.',409);
    $db->beginTransaction();try{$update=$db->prepare("UPDATE attendance a JOIN children c ON c.id=a.child_id SET a.status='PICKED_UP',a.picked_up_at=NOW() WHERE a.service_session_id=? AND c.family_id=? AND a.status='CHECKED_IN'");$update->execute([$code['service_session_id'],$code['family_id']]);$db->prepare('UPDATE service_pickup_codes SET collected_at=NOW(),collected_by_staff_user_id=? WHERE id=? AND collected_at IS NULL')->execute([$actor['id'],$id]);api_audit($db,$actor,'PICKUP_COMPLETED','PickupCode',$id,['pickupCode'=>$code['display_code'],'verificationMethod'=>$verificationMethod,'childrenReleased'=>$update->rowCount()]);$db->commit();api_ok(['pickupCode'=>$code['display_code'],'childrenReleased'=>$update->rowCount(),'completed'=>true]);}catch(Throwable $e){$db->rollBack();throw $e;}
}
function api_set_access(PDO $db,int $id): never { $actor=api_actor($db,true);if($id===(int)$actor['id'])api_error('FORBIDDEN','A Super Admin cannot change their own access level.',403);$v=api_input();$next=$v['accessLevel']??'';if(!in_array($next,['TPK_SUPER_ADMIN','TPK_ADMIN'],true))api_error('VALIDATION_ERROR','Choose TPK_SUPER_ADMIN or TPK_ADMIN.',422);$s=$db->prepare('SELECT access_level FROM staff_users WHERE id=? AND campus_id=?');$s->execute([$id,$actor['campus_id']]);$previous=$s->fetchColumn();if($previous===false)api_error('STAFF_NOT_FOUND','Team member not found.',404);if($previous===$next)api_ok(['id'=>$id,'accessLevel'=>$next]);$db->beginTransaction();try{$db->prepare('UPDATE staff_users SET access_level=? WHERE id=?')->execute([$next,$id]);$db->prepare('INSERT INTO staff_access_audits(staff_user_id,previous_access_level,next_access_level,changed_by_staff_user_id) VALUES(?,?,?,?)')->execute([$id,$previous,$next,$actor['id']]);api_audit($db,$actor,'STAFF_ACCESS_UPDATED','StaffUser',$id,['from'=>$previous,'to'=>$next]);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}api_ok(['id'=>$id,'accessLevel'=>$next]); }
function api_my_profile(PDO $db): never {
    $actor=api_actor($db);$s=$db->prepare('SELECT s.id AS staffUserId,s.email,s.access_level AS accessLevel,s.team_status AS teamStatus,s.joined_at AS joinedAt,c.name AS campus,p.title,p.first_name AS firstName,p.last_name AS lastName,p.birth_date AS birthDate,p.whatsapp_number AS whatsappNumber,p.mobile_number AS mobileNumber,p.profile_image_url AS profileImageUrl,p.whatsapp_verified_at AS whatsappVerifiedAt FROM staff_users s JOIN teacher_profiles p ON p.staff_user_id=s.id JOIN campuses c ON c.id=s.campus_id WHERE s.id=?');$s->execute([$actor['id']]);$profile=$s->fetch();if(!$profile)api_error('PROFILE_NOT_FOUND','Your staff profile is not available.',404);
    if(api_method()==='GET') api_ok($profile);
    $v=api_input();$allowed=['title'=>'title','firstName'=>'first_name','lastName'=>'last_name','birthDate'=>'birth_date','email'=>'email','mobileNumber'=>'mobile_number'];$profileSets=[];$userSets=[];$params=[];$userParams=[];
    foreach($allowed as $input=>$column)if(array_key_exists($input,$v)){if($input==='title'&&!in_array($v[$input],['Auntie','Uncle'],true))api_error('VALIDATION_ERROR','Choose Auntie or Uncle.',422);if($input==='email'&&!filter_var($v[$input],FILTER_VALIDATE_EMAIL))api_error('VALIDATION_ERROR','Enter a valid email address.',422);if($input==='mobileNumber'&&$v[$input]!==null&&$v[$input]!==''){ $number=tpk_normalize_nigerian_phone($v[$input]);if(!$number)api_error('VALIDATION_ERROR','Enter a valid Nigerian mobile number.',422);$profileSets[]='mobile_number=?';$params[]=$number;$profileSets[]='mobile_number_normalized=?';$params[]=$number;continue;}if($input==='email'){$userSets[]='email=?';$userParams[]=strtolower(trim($v[$input]));}else{$profileSets[]="$column=?";$params[]=$v[$input];}}
    if(!$profileSets&&!$userSets)api_error('VALIDATION_ERROR','No editable profile fields were supplied.',422);$db->beginTransaction();try{if($profileSets){$params[]=$actor['id'];$db->prepare('UPDATE teacher_profiles SET '.implode(',',$profileSets).' WHERE staff_user_id=?')->execute($params);}if($userSets){$userParams[]=$actor['id'];$db->prepare('UPDATE staff_users SET '.implode(',',$userSets).' WHERE id=?')->execute($userParams);}api_audit($db,$actor,'STAFF_PROFILE_UPDATED','StaffUser',(int)$actor['id'],array_keys($v));$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}api_ok(['updated'=>true]);
}
function api_profile_photo(PDO $db): never {
    $actor=api_actor($db);if(empty($_FILES['profilePhoto']))api_error('VALIDATION_ERROR','Choose a profile photo to upload.',422);try{$url=tpk_store_profile_photo($_FILES['profilePhoto'],(int)$actor['id']);}catch(Throwable $e){api_error('PROFILE_PHOTO_INVALID',$e->getMessage(),422);}$db->prepare('UPDATE teacher_profiles SET profile_image_url=? WHERE staff_user_id=?')->execute([$url,$actor['id']]);api_audit($db,$actor,'STAFF_PROFILE_PHOTO_UPDATED','StaffUser',(int)$actor['id']);api_ok(['profileImageUrl'=>$url]);
}
function api_remove_profile_photo(PDO $db): never { $actor=api_actor($db);$db->prepare('UPDATE teacher_profiles SET profile_image_url=NULL WHERE staff_user_id=?')->execute([$actor['id']]);api_audit($db,$actor,'STAFF_PROFILE_PHOTO_REMOVED','StaffUser',(int)$actor['id']);api_ok(['profileImageUrl'=>null]); }
function api_team(PDO $db): never {
    $actor=api_actor($db,true);$s=$db->prepare("SELECT s.id,s.name,s.email,s.access_level AS accessLevel,s.team_status AS teamStatus,s.account_status AS accountStatus,s.joined_at AS joinedAt,p.title,p.first_name AS firstName,p.last_name AS lastName,p.profile_image_url AS profileImageUrl,p.whatsapp_number AS whatsappNumber,GROUP_CONCAT(DISTINCT c.name ORDER BY c.name SEPARATOR ', ') AS assignedClasses FROM staff_users s LEFT JOIN teacher_profiles p ON p.staff_user_id=s.id LEFT JOIN staff_class_assignments sca ON sca.staff_user_id=s.id AND sca.is_active=1 LEFT JOIN classes c ON c.id=sca.class_id WHERE s.campus_id=? GROUP BY s.id,p.title,p.first_name,p.last_name,p.profile_image_url,p.whatsapp_number ORDER BY p.first_name,p.last_name");$s->execute([$actor['campus_id']]);api_ok($s->fetchAll());
}
function api_set_team_status(PDO $db,int $id): never {
    $actor=api_actor($db,true);if($id===(int)$actor['id'])api_error('FORBIDDEN','A Super Admin cannot change their own team status.',403);$v=api_input();$next=$v['teamStatus']??'';if(!in_array($next,['ACTIVE','PROBATION','INACTIVE'],true))api_error('VALIDATION_ERROR','Choose ACTIVE, PROBATION, or INACTIVE.',422);$s=$db->prepare('SELECT team_status FROM staff_users WHERE id=? AND campus_id=?');$s->execute([$id,$actor['campus_id']]);$previous=$s->fetchColumn();if($previous===false)api_error('STAFF_NOT_FOUND','Team member not found.',404);if($previous===$next)api_ok(['id'=>$id,'teamStatus'=>$next]);$db->beginTransaction();try{$db->prepare('UPDATE staff_users SET team_status=?,is_active=? WHERE id=?')->execute([$next,$next==='INACTIVE'?0:1,$id]);$db->prepare('INSERT INTO staff_team_status_audits(staff_user_id,previous_team_status,next_team_status,changed_by_staff_user_id) VALUES(?,?,?,?)')->execute([$id,$previous,$next,$actor['id']]);api_audit($db,$actor,'STAFF_TEAM_STATUS_UPDATED','StaffUser',$id,['from'=>$previous,'to'=>$next]);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}api_ok(['id'=>$id,'teamStatus'=>$next]);
}

